with w as(select * from public.works where id between 987162001 and 987162003) select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(w) order by id) from w),'editions',(select jsonb_agg(to_jsonb(e) order by id) from public.editions e where work_id in(select id from w)),'authors',(select jsonb_agg(to_jsonb(a) order by id) from public.authors a where id in(select author_id from w))) as readback;
